Lemma ge_W2 : forall (fx : FPState) regs (m : word -> option byte) (s pixs : Z),
  (4096 + 144 <= s <= 2 ^ 47)%Z ->
  (0 <= pixs < 2 ^ 64)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 144) ->
  getr regs 8 = Z_to_bv 64 pixs ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 190384) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 105628) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 190396 /\ getr regs' 2 = Z_to_bv 64 (s - 144) /\ getr regs' 10 = Z_to_bv 64 0 /\ getr regs' 11 = Z_to_bv 64 pixs /\
