Lemma ge_Xerr : forall (fx : FPState) regs (m : word -> option byte) (s a0v : Z) (ret : word) (v1 v8 v9 v18 v19 v20 v21 v22 v23 v24 v25 v26 : word),
  (4096 + 144 <= s <= 2 ^ 47)%Z ->
  (0 <= a0v < 2 ^ 64)%Z ->
  ret_ok ret ->
  v1 = ret ->
  rdn SEGS m (Z_to_bv 64 (s - 8)) 8 = Some (word_to_le_bytes 8 v1) ->
  rdn SEGS m (Z_to_bv 64 (s - 16)) 8 = Some (word_to_le_bytes 8 v8) ->
