Lemma ge_B : forall (fx : FPState) regs (m : word -> option byte) (s pixs keli : Z),
  (4096 + 144 <= s <= 2 ^ 47)%Z ->
  (0 <= pixs < 2 ^ 64)%Z ->
  (4096 <= keli)%Z ->
  (keli + 24 <= s - 144 \/ s <= keli)%Z ->
  (keli + 24 <= 2 ^ 47)%Z ->
  rdn SEGS m (Z_to_bv 64 keli) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 41)) ->
  rdn SEGS m (Z_to_bv 64 (keli + 4)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 41)) ->
  rdn SEGS m (Z_to_bv 64 (keli + 8)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 20)) ->
  rdn SEGS m (Z_to_bv 64 (keli + 12)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 20)) ->
  store_ok SEGS m (Z_to_bv 64 (s - 144)) 144 = true ->
  getr regs 2 = Z_to_bv 64 (s - 144) ->
  getr regs 8 = Z_to_bv 64 pixs ->
  getr regs 10 = Z_to_bv 64 keli ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 190016) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 112404) M' rom /\
      rinv [((s - 136)%Z, 8%Z); ((s - 124)%Z, 16%Z)] m M' /\ rdn SEGS M' (Z_to_bv 64 (s - 136)) 8 = Some (Z_to_le_bytes 8 keli) /\
      rdn SEGS M' (Z_to_bv 64 (s - 112)) 4 = Some (Z_to_le_bytes 4 41) /\ rdn SEGS M' (Z_to_bv 64 (s - 116)) 4 = Some (Z_to_le_bytes 4 41) /\
      rdn SEGS M' (Z_to_bv 64 (s - 120)) 4 = Some (Z_to_le_bytes 4 20) /\ rdn SEGS M' (Z_to_bv 64 (s - 124)) 4 = Some (Z_to_le_bytes 4 20) /\
      getr regs' 1 = Z_to_bv 64 190072 /\ getr regs' 2 = Z_to_bv 64 (s - 144) /\ getr regs' 10 = Z_to_bv 64 pixs /\
      getr regs' 11 = Z_to_bv 64 20 /\ getr regs' 12 = Z_to_bv 64 21 /\ getr regs' 13 = Z_to_bv 64 20 /\ getr regs' 14 = Z_to_bv 64 21 /\
