Lemma ge_C : forall (fx : FPState) regs (m : word -> option byte) (s pixt w h : Z),
  (4096 + 144 <= s <= 2 ^ 47)%Z ->
  (4096 <= pixt < 2 ^ 47)%Z ->
  (0 <= w < 2 ^ 31)%Z ->
  (0 <= h < 2 ^ 31)%Z ->
  rdn SEGS m (Z_to_bv 64 (s - 100)) 4 = Some (Z_to_le_bytes 4 w) ->
  rdn SEGS m (Z_to_bv 64 (s - 104)) 4 = Some (Z_to_le_bytes 4 h) ->
  store_ok SEGS m (Z_to_bv 64 (s - 144)) 144 = true ->
  getr regs 2 = Z_to_bv 64 (s - 144) ->
  getr regs 10 = Z_to_bv 64 pixt ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 190072) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 102180) M' rom /\
      rinv [((s - 144)%Z, 8%Z)] m M' /\ rdn SEGS M' (Z_to_bv 64 (s - 144)) 8 = Some (Z_to_le_bytes 8 pixt) /\
      getr regs' 1 = Z_to_bv 64 190100 /\ getr regs' 2 = Z_to_bv 64 (s - 144) /\ getr regs' 18 = Z_to_bv 64 pixt /\
      getr regs' 10 = Z_to_bv 64 w /\ getr regs' 11 = Z_to_bv 64 h /\ getr regs' 12 = Z_to_bv 64 8 /\
