Lemma ge_Cn : forall (fx : FPState) regs (m : word -> option byte) (s : Z),
  (4096 + 144 <= s <= 2 ^ 47)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 144)) 144 = true ->
  getr regs 2 = Z_to_bv 64 (s - 144) ->
  getr regs 10 = Z_to_bv 64 0 ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 190072) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 182304) M' rom /\
      rinv [((s - 144)%Z, 8%Z)] m M' /\ rdn SEGS M' (Z_to_bv 64 (s - 144)) 8 = Some (Z_to_le_bytes 8 0) /\
      getr regs' 1 = Z_to_bv 64 190848 /\ getr regs' 2 = Z_to_bv 64 (s - 144) /\ getr regs' 10 = Z_to_bv 64 (s - 136) /\
      regs_agree (fun r => In r [1; 10]%list) regs regs').
