Lemma ge_Cn2 : forall (fx : FPState) regs (m : word -> option byte) (s : Z),
  (4096 + 144 <= s <= 2 ^ 47)%Z ->
  (438272 <= s - 144)%Z ->
  (forall j, (230424 <= j < 230584)%Z -> m (Z_to_bv 64 j) = None) ->
  (forall j, (234720 <= j < 234728)%Z -> m (Z_to_bv 64 j) = None) ->
  getr regs 2 = Z_to_bv 64 (s - 144) ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 190848) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 97396) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 190444 /\ getr regs' 2 = Z_to_bv 64 (s - 144) /\
      getr regs' 10 = Z_to_bv 64 72295 /\ getr regs' 11 = Z_to_bv 64 73598 /\ getr regs' 12 = Z_to_bv 64 0 /\
