Lemma ge_D : forall (fx : FPState) regs (m : word -> option byte) (s pixt pixd rkel datat datad wplt wpld : Z),
  (4096 + 144 <= s <= 2 ^ 47)%Z ->
  (4096 <= pixt)%Z ->
  (pixt + 64 <= 2 ^ 47)%Z ->
  (4096 <= pixd)%Z ->
  (pixd + 64 <= 2 ^ 47)%Z ->
  (0 <= datat < 2 ^ 64)%Z ->
  (0 <= datad < 2 ^ 64)%Z ->
  (0 <= wplt < 2 ^ 31)%Z ->
  (0 <= wpld < 2 ^ 31)%Z ->
  (0 <= rkel < 2 ^ 64)%Z ->
  rdn SEGS m (Z_to_bv 64 (pixt + 56)) 8 = Some (Z_to_le_bytes 8 datat) ->
  rdn SEGS m (Z_to_bv 64 (pixt + 16)) 4 = Some (Z_to_le_bytes 4 wplt) ->
  rdn SEGS m (Z_to_bv 64 (pixd + 56)) 8 = Some (Z_to_le_bytes 8 datad) ->
  rdn SEGS m (Z_to_bv 64 (pixd + 16)) 4 = Some (Z_to_le_bytes 4 wpld) ->
  getr regs 2 = Z_to_bv 64 (s - 144) ->
  getr regs 10 = Z_to_bv 64 pixd ->
  getr regs 18 = Z_to_bv 64 pixt ->
  getr regs 21 = Z_to_bv 64 rkel ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 190100) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 190152) M' rom /\
      M' = m /\ getr regs' 2 = Z_to_bv 64 (s - 144) /\ getr regs' 8 = Z_to_bv 64 datat /\ getr regs' 9 = Z_to_bv 64 datad /\ getr regs' 18 = Z_to_bv 64 wplt /\
      getr regs' 20 = Z_to_bv 64 pixd /\ getr regs' 21 = Z_to_bv 64 rkel /\ getr regs' 10 = Z_to_bv 64 wpld /\
      regs_agree (fun r => In r [1; 8; 9; 10; 18; 19; 20]%list) regs regs').
