Lemma ge_E : forall (fx : FPState) regs (m : word -> option byte) (s : Z),
  (4096 + 144 <= s <= 2 ^ 47)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 144) ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 190816) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 182304) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 190824 /\ getr regs' 2 = Z_to_bv 64 (s - 144) /\ getr regs' 10 = Z_to_bv 64 (s - 136) /\
      regs_agree (fun r => In r [1; 10]%list) regs regs').
