Lemma ge_F : forall (fx : FPState) regs (m : word -> option byte) (s : Z),
  (4096 + 144 <= s <= 2 ^ 47)%Z ->
  getr regs 2 = Z_to_bv 64 (s - 144) ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 190824) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 103464) M' rom /\
      M' = m /\ getr regs' 1 = Z_to_bv 64 190832 /\ getr regs' 2 = Z_to_bv 64 (s - 144) /\ getr regs' 10 = Z_to_bv 64 (s - 144) /\
      regs_agree (fun r => In r [1; 10]%list) regs regs').
Proof.
